<script setup>
import { computed, ref, watch } from "vue";
import { useI18n } from "vue-i18n";
import { app } from "@/utils/app.js";
import AppDialog from "@/components/AppDialog.vue";
import { requiredValidator } from "@/@core/utils/validators";

/**
 * One form for every address level (province > district > commune > village),
 * used by AddEditProvinceDialog / District / Commune / Village.
 *
 * - Creating: pick the parent levels, type the names. The code is generated by
 *   the server (next number under the parent); the expected code is previewed.
 * - Editing: only the names change. The parent is shown but fixed, because the
 *   server keeps the code, and clients / branches store the code as their address.
 */
const props = defineProps({
  level: { type: String, required: true }, // province | district | commune | village
  itemData: { type: Object, default: () => ({}) },
  isDialogVisible: { type: Boolean, required: true },
  loading: { type: Boolean, default: false },
});

const emit = defineEmits(["onCreate", "onUpdate", "update:isDialogVisible"]);

const { t, locale } = useI18n();

const LEVELS = {
  province: { title: "Province", icon: "tabler-map-2", parents: [], parentKey: null, list: "provinces", kh: "ខេត្តកំពង់ចាម", en: "Kampong Cham Province" },
  district: { title: "District", icon: "tabler-map-pin", parents: ["province"], parentKey: "province_code", list: "districts", kh: "ម៉ាឡៃ", en: "Malai" },
  commune: { title: "Commune", icon: "tabler-map-pin", parents: ["province", "district"], parentKey: "district_code", list: "communes", kh: "អូរឫស្សី", en: "Ou Reusey" },
  village: { title: "Village", icon: "tabler-home-2", parents: ["province", "district", "commune"], parentKey: "commune_code", list: "villages", kh: "ព្រៃគុប", en: "Prey Kub" },
};
const PARENT_ICON = { province: "tabler-map-2", district: "tabler-map-pin", commune: "tabler-map-pin" };
const PARENT_LIST = { province: "provinces", district: "districts", commune: "communes" };
const CHILD_KEY = { province: "province_code", district: "district_code", commune: "commune_code" };

const cfg = computed(() => LEVELS[props.level]);

// Address lists, read once per opening (app() parses local storage each call)
const data = ref({ provinces: [], districts: [], communes: [], villages: [] });

// Selected parent codes (province / district / commune)
const path = ref({ province: null, district: null, commune: null });
const form = ref({ name_kh: "", name_en: "" });
const isEdit = computed(() => !!props.itemData?.id);

const name = (x) => (x ? (locale.value === "km" ? x.name_kh : x.name_en || x.name_kh) : "");

// Work out the full parent path from the item's own parent code
const fillPath = (item) => {
  const p = { province: null, district: null, commune: null };
  const d = data.value;
  if (props.level === "district") p.province = Number(item.province_code) || null;
  if (props.level === "commune") {
    p.district = Number(item.district_code) || null;
    p.province = d.districts.find((x) => x.code === p.district)?.province_code ?? null;
  }
  if (props.level === "village") {
    p.commune = Number(item.commune_code) || null;
    p.district = d.communes.find((x) => x.code === p.commune)?.district_code ?? null;
    p.province = d.districts.find((x) => x.code === p.district)?.province_code ?? null;
  }
  path.value = p;
};

watch(
  () => [props.isDialogVisible, props.itemData],
  ([open]) => {
    if (!open) return;
    const a = app() || {};
    data.value = {
      provinces: a.provinces || [],
      districts: a.districts || [],
      communes: a.communes || [],
      villages: a.villages || [],
    };
    form.value = { name_kh: props.itemData?.name_kh || "", name_en: props.itemData?.name_en || "" };
    fillPath(props.itemData || {});
  },
  { immediate: true },
);

// Options for each parent picker, filtered by the level above
const options = (parent) => {
  const d = data.value;
  if (parent === "province") return d.provinces;
  if (parent === "district") return path.value.province ? d.districts.filter((x) => x.province_code === path.value.province) : [];
  if (parent === "commune") return path.value.district ? d.communes.filter((x) => x.district_code === path.value.district) : [];
  return [];
};

// Picking a level clears the ones below it
const pick = (parent, code) => {
  path.value[parent] = code;
  const order = ["province", "district", "commune"];
  for (const lower of order.slice(order.indexOf(parent) + 1)) path.value[lower] = null;
};

// Direct parent code (what the server saves)
const parentCode = computed(() => {
  const parents = cfg.value.parents;
  return parents.length ? path.value[parents[parents.length - 1]] : null;
});

// "ខេត្តបន្ទាយមានជ័យ › ប៉ោយប៉ែត › អូរឫស្សី"
const breadcrumb = computed(() =>
  cfg.value.parents
    .map((p) => name(data.value[PARENT_LIST[p]].find((x) => x.code === path.value[p])))
    .filter(Boolean),
);

// Siblings under the same parent (for the duplicate check and the code preview)
const siblings = computed(() => {
  const list = data.value[cfg.value.list] || [];
  if (!cfg.value.parentKey) return list;
  return parentCode.value ? list.filter((x) => x[cfg.value.parentKey] === parentCode.value) : [];
});

// Same as the server: next number under the parent (province: its id)
const codePreview = computed(() => {
  if (isEdit.value) return props.itemData.code;
  if (props.level === "province") return null;
  if (!parentCode.value) return null;
  const max = Math.max(0, ...siblings.value.map((x) => Number(x.code) || 0));
  return max ? max + 1 : null;
});

const duplicateRule = (v) => {
  const value = (v || "").trim();
  if (!value) return true;
  const clash = siblings.value.some((x) => x.id !== props.itemData?.id && (x.name_kh || "").trim() === value);
  return !clash || t("This name already exists here");
};
const parentRule = (parent) => () => !!path.value[parent] || t("This field is required");

const close = () => emit("update:isDialogVisible", false);

const onSubmit = async (validation) => {
  const { valid } = (await validation) || { valid: true };
  if (!valid || props.loading) return;

  const payload = {
    ...props.itemData,
    name_kh: form.value.name_kh.trim(),
    name_en: form.value.name_en.trim() || null,
  };
  // Every parent code (province_code / district_code / commune_code); the
  // server uses the direct parent, the others are sent like before
  for (const p of cfg.value.parents) payload[CHILD_KEY[p]] = path.value[p];

  emit(isEdit.value ? "onUpdate" : "onCreate", payload, () => {});
};
</script>

<template>
  <AppDialog
    :title="`${isEdit ? 'Update' : 'Create'} ${cfg.title}`"
    :title-icon="cfg.icon"
    :is-dialog-visible="isDialogVisible"
    @update:is-dialog-visible="(v) => !v && close()"
    :width="620"
    is-footer
    is-submit
    :submit-text="isEdit ? 'Update' : 'Create'"
    :submit-icon="isEdit ? 'tabler-device-floppy' : 'tabler-plus'"
    :submit-color="isEdit ? 'warning' : 'primary'"
    :loading="loading"
    @on-submit="onSubmit"
  >
    <div class="address-form">
      <!-- Where it belongs -->
      <section v-if="cfg.parents.length">
        <div class="section-title">
          <span class="section-title__icon"><VIcon icon="tabler-map-search" size="15" /></span>
          {{ $t("Location") }}
        </div>

        <!-- Editing: the parent is fixed -->
        <div v-if="isEdit" class="path path--fixed">
          <VIcon icon="tabler-lock" size="16" />
          <span v-if="breadcrumb.length">{{ breadcrumb.join(" › ") }}</span>
          <span v-else class="text-medium-emphasis">—</span>
        </div>

        <!-- Creating: pick each level -->
        <VRow v-else>
          <VCol v-for="p in cfg.parents" :key="p" cols="12" :sm="cfg.parents.length === 3 && p === 'commune' ? 12 : 6">
            <AppAutocomplete
              :model-value="path[p]"
              :items="options(p)"
              item-value="code"
              :item-title="name"
              :prepend-inner-icon="PARENT_ICON[p]"
              :disabled="p !== 'province' && !options(p).length"
              :rules="[parentRule(p)]"
              @update:model-value="(code) => pick(p, code)"
            >
              <template #label>{{ $t(p.charAt(0).toUpperCase() + p.slice(1)) }} <span class="text-error">*</span></template>
            </AppAutocomplete>
          </VCol>
        </VRow>

        <div v-if="!isEdit && breadcrumb.length" class="path mt-3">
          <VIcon icon="tabler-route" size="16" />
          <span>{{ breadcrumb.join(" › ") }} › <b>{{ form.name_kh || "…" }}</b></span>
        </div>
      </section>

      <!-- Names -->
      <section>
        <div class="section-title">
          <span class="section-title__icon"><VIcon :icon="cfg.icon" size="15" /></span>
          {{ $t(cfg.title) }}
          <VChip v-if="codePreview" size="x-small" label class="ms-1">
            {{ isEdit ? $t("Code") : $t("New code") }} {{ codePreview }}
          </VChip>
        </div>
        <VRow>
          <VCol cols="12" sm="6">
            <AppTextField
              v-model="form.name_kh"
              :placeholder="cfg.kh"
              maxlength="255"
              :rules="[requiredValidator, duplicateRule]"
            >
              <template #label>{{ $t("Name Khmer") }} <span class="text-error">*</span></template>
            </AppTextField>
          </VCol>
          <VCol cols="12" sm="6">
            <AppTextField v-model="form.name_en" :placeholder="cfg.en" maxlength="255">
              <template #label>{{ $t("Name English") }}</template>
            </AppTextField>
          </VCol>
        </VRow>
      </section>
    </div>
  </AppDialog>
</template>

<style scoped>
.address-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* Section headings (same style as the other dialogs) */
.section-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
  font-size: 14px;
  font-weight: 500;
}

.section-title::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(var(--v-border-color), var(--v-border-opacity));
}

.section-title__icon {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  color: rgb(var(--v-theme-primary));
  background: rgba(var(--v-theme-primary), 0.1);
}

/* Breadcrumb of the parent levels */
.path {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  font-size: 13px;
  color: rgb(var(--v-theme-primary));
  background: rgba(var(--v-theme-primary), 0.06);
}

.path--fixed {
  color: rgba(var(--v-theme-on-surface), var(--v-high-emphasis-opacity));
  background: rgba(var(--v-theme-on-surface), 0.04);
}

.path--fixed .v-icon {
  color: rgba(var(--v-theme-on-surface), var(--v-medium-emphasis-opacity));
}
</style>
